 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();
  group.name = config.id || 'quote-panel-journal';

  const colors = config.intent?.visualSpec?.colors || config.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const bodyGroup = new ctx.THREE.Group();
  group.add(bodyGroup);

  const applied = [];
  const texUrl = config.imageUrl || '/prism-mock/home/nodes/feature-card.png';
  const card = { tex: null, mesh: null, edgeMat: null, edgeMeshes: [], geometries: [] };

  const aspect = 512 / 320;
  const width = 2.5;
  const height = width / aspect;
  const thickness = 0.035;

  const surfaceMat = new MeshBasicNodeMaterial({
    color: colors.surface,
    transparent: true,
    side: ctx.THREE.DoubleSide,
  });

  const cardGeo = new ctx.THREE.PlaneGeometry(width, height);
  card.geometries.push(cardGeo);
  const cardMesh = new ctx.THREE.Mesh(cardGeo, surfaceMat);
  cardMesh.name = 'card-face';
  bodyGroup.add(cardMesh);
  card.mesh = cardMesh;

  const edgeMat = new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0,
    depthWrite: false,
  });
  card.edgeMat = edgeMat;

  const edgeGeos = [
    new ctx.THREE.PlaneGeometry(width + thickness * 2, thickness),
    new ctx.THREE.PlaneGeometry(width + thickness * 2, thickness),
    new ctx.THREE.PlaneGeometry(thickness, height),
    new ctx.THREE.PlaneGeometry(thickness, height),
  ];
  card.geometries.push(...edgeGeos);

  const topEdge = new ctx.THREE.Mesh(edgeGeos[0], edgeMat);
  topEdge.position.set(0, height / 2 + thickness / 2, 0.01);
  const bottomEdge = new ctx.THREE.Mesh(edgeGeos[1], edgeMat);
  bottomEdge.position.set(0, -(height / 2 + thickness / 2), 0.01);
  const leftEdge = new ctx.THREE.Mesh(edgeGeos[2], edgeMat);
  leftEdge.position.set(-(width / 2 + thickness / 2), 0, 0.01);
  const rightEdge = new ctx.THREE.Mesh(edgeGeos[3], edgeMat);
  rightEdge.position.set(width / 2 + thickness / 2, 0, 0.01);

  card.edgeMeshes.push(topEdge, bottomEdge, leftEdge, rightEdge);
  bodyGroup.add(topEdge, bottomEdge, leftEdge, rightEdge);

  ctx.textureLoader.loadTexture(texUrl).then((tex) => {
    card.tex = tex;
    try {
      tex.colorSpace = ctx.THREE.SRGBColorSpace;
    } catch (_) {}
    tex.needsUpdate = true;
    surfaceMat.map = tex;
    surfaceMat.needsUpdate = true;
  });

  const primitives = config.cinematicPrimitives || config.intent?.visualSpec?.cinematicPrimitives || [];
  primitives.forEach((p) => {
    if (ctx.primitives && typeof ctx.primitives[p.name] === 'function') {
      applied.push(ctx.primitives[p.name](group, p.params || {}));
    }
  });

  group.userData.handlers = {
    hover: (payload) => {
      const entering = typeof payload === 'boolean' ? payload : payload?.entering ?? true;
      gsap.to(bodyGroup.position, {
        y: entering ? 0.15 : 0,
        duration: 0.35,
        ease: 'power2.out',
      });
      if (card.edgeMat) {
        gsap.to(card.edgeMat, {
          opacity: entering ? 0.75 : 0,
          duration: 0.3,
          ease: 'power2.out',
        });
      }
    },
    click: () => {
      gsap.to(bodyGroup.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(2)',
        yoyo: true,
        repeat: 1,
        onComplete: () => {
          ctx.emit('hub-journal.select', {
            from: config.id,
            hubId: 'hub-journal',
          });
        },
      });
    },
  };

  group.userData.cleanup = () => {
    gsap.killTweensOf(bodyGroup.position);
    gsap.killTweensOf(bodyGroup.scale);
    if (card.edgeMat) gsap.killTweensOf(card.edgeMat);

    applied.forEach((inst) => {
      try {
        inst.timeline?.kill();
      } catch (_) {}
      try {
        inst.cleanup?.();
      } catch (_) {}
    });

    surfaceMat.dispose();
    edgeMat.dispose();
    card.geometries.forEach((g) => g.dispose());
    if (card.tex) card.tex.dispose();

    if (group.parent) group.parent.remove(group);
    group.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material && obj.material !== surfaceMat && obj.material !== edgeMat) {
        obj.material.dispose();
      }
    });
  };

  return group;
}
